import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A sheet's pool as the store holds it: a trimmed name, on the sheet at most once, and its members, each a person
 *  of the sheet at most once with a share percent. `totalShare` is the members' shares added up, a retired member's
 *  (one with a retirement date set, whatever the date) counting as given; `balanced` is whether it is exactly 100.00. */
export type Pool = { id: number; name: string; totalShare: string; balanced: boolean; members: PoolMember[] };

/** A pool's member: the person, or another pool (`poolId`; the other null), its name, its share (two decimals) and its
 *  cut of the pool's pot (two decimals; "" when the pool is not balanced or has no pot, or every member is retired, or the member's dates do not include the
 *  sheet's today — such a member is left out of the total share and balance too). A pool that is a member of
 *  none has the sheet's pot; a pool that is a member of another has its cut there as its pot. */
export type PoolMember = { personId: number | null; poolId: number | null; name: string; share: string; cut: string };

export const poolsQueryKey = (sheetId: string) => ['sheet', sheetId, 'pools'] as const;

export const poolsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/pools`;

/** The sheet's pools, in the order they were added. */
export function usePools() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: poolsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Pool[]>(poolsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Person } from '../people/people';
import { usePools, type Pool } from './pools';

/** The cuts of the given person (every person when null) across every pool they are a member of, added up; a pool
 *  that shows no cuts adds nothing. Summed in whole cents, so the total is exact. */
function cutTotalOf(pools: Pool[], personId: number | null): string {
  const cents = pools
    .flatMap((p) => p.members)
    .filter((m) => m.personId != null && (personId == null || m.personId === personId) && m.cut !== '')
    .reduce((n, m) => n + Math.round(Number(m.cut) * 100), 0);
  return (cents / 100).toFixed(2);
}

// A person's cut total: their cuts across every pool they are a member of, added up.
function CutTotalHeader() {
  return <th>Cut total</th>;
}

function PersonCutTotal({ person }: { person: Person }) {
  const pools = usePools();
  return <td data-testid="person-cut-total">{cutTotalOf(pools.data ?? [], person.id)}</td>;
}

// The sheet's cut total: everyone's cut total added up.
function CutTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const pools = usePools();
  if (!user || !sheet) return null;
  return (
    <p>
      Cut in total <strong data-testid="rollup-cut-total">{cutTotalOf(pools.data ?? [], null)}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 10.5, Component: CutTotalHeader }),
  PersonCells.fill({ order: 10.5, Component: PersonCutTotal }),
  HomeMain.fill({ order: 30.5, Component: CutTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A person of a crew: their id and name. */
export type CrewPerson = { id: number; name: string };

/** A sheet's crew as the store holds it: a trimmed name, on the sheet at most once, its lead (a person of the sheet)
 *  and its members, each a person of the sheet at most once and never the lead, in the order they were added. */
export type Crew = { id: number; name: string; lead: CrewPerson | null; members: CrewPerson[] };

export const crewsQueryKey = (sheetId: string) => ['sheet', sheetId, 'crews'] as const;

export const crewsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/crews`;

/** The sheet's crews, in the order they were added. */
export function useCrews() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: crewsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Crew[]>(crewsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
