37	            Pool member = pools.findByIdAndSheetId(request.memberPoolId(), pool.getSheetId())
38	                    .orElseThrow(() -> new InvalidPoolException("There is no such pool on the sheet."));
39	            if (member.getId().equals(pool.getId())) {
