559	/** Reads the member's person and share from the body; refuses a missing person (or pool), or a share that is not a number
560	 *  with at most two decimals, more than 0.00 and at most 100.00, a date that is not YYYY-MM-DD, or a to-date before
561	 *  the from-date. */
562	public class ValidatePoolMember {
563	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
564	
565	    public void validate(@RequestBody PoolMemberRequest request, Out<ValidPoolMember> body) throws InvalidPoolException {
566	        if (request == null || (request.personId() == null) == (request.memberPoolId() == null)) {
567	            throw new InvalidPoolException("Choose a person or a pool for the pool.");
568	        }
569	        String share = request.share() == null ? "" : request.share().trim();
570	        if (!share.matches("\\d{1,3}(\\.\\d{1,2})?")) {
571	            throw new InvalidPoolException("A share is a percent with at most two decimals.");
572	        }
573	        BigDecimal value = new BigDecimal(share).setScale(2);
574	        if (value.signum() <= 0 || value.compareTo(HUNDRED) > 0) {
575	            throw new InvalidPoolException("A share must be more than 0.00 and at most 100.00.");
576	        }
577	        LocalDate from = date(request.from());
578	        LocalDate to = date(request.to());
579	        if (from != null && to != null && to.isBefore(from)) {
580	            throw new InvalidPoolException("A to-date must not be before the from-date.");
581	        }
582	        body.set(new ValidPoolMember(request.personId(), request.memberPoolId(), value, from, to));
583	    }
584	
585	    private static LocalDate date(String value) throws InvalidPoolException {
586	        if (value == null || value.isBlank()) {
587	            return null;
588	        }
589	        try {
590	            return LocalDate.parse(value.trim());
591	        } catch (DateTimeParseException e) {
592	            throw new InvalidPoolException("A date must be YYYY-MM-DD.");
593	        }
594	    }
595	}
